INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20MF939', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A dermatology clinic randomly assigns $120$ patients with moderate acne to two groups. One group uses a new topical treatment, and the other group uses an existing standard treatment. After $14$ weeks, patients in the new treatment group have significantly fewer acne lesions on average. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new treatment is effective for all acne patients everywhere."},{"key":"B","text":"Patients who preferred the new treatment had naturally clearer skin to begin with."},{"key":"C","text":"The new treatment likely caused the reduction in acne lesions among the patients in this experiment."},{"key":"D","text":"There is an association between the new treatment and fewer lesions, but causation cannot be determined."}]$lyceon_json$::jsonb, 'C', NULL, E'Because patients were randomly assigned to groups, this is a randomized experiment. Random assignment controls for confounding variables such as skin type, diet, or prior treatment history, so a causal conclusion about the treatment''s effect is appropriate for the study population. The claim about all acne patients everywhere overgeneralizes beyond the study''s population of moderate acne patients at one clinic. The claim about patients preferring the new treatment contradicts the study design — random assignment means patients did not choose their treatment, so self-selection bias is not a factor. The claim that causation cannot be determined applies to observational studies, not randomized experiments, and reflects incomplete understanding of when causal inference is warranted.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20MPOE5', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{49x^2 - 121}{7x + 11}$ for $x \\neq -\\frac{11}{7}$?', NULL, $lyceon_json$[{"key":"A","text":"$7x + 11$"},{"key":"B","text":"$7x - 11$"},{"key":"C","text":"$49x - 11$"},{"key":"D","text":"$7x^2 - 11$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $49x^2 - 121$ is a difference of squares: $(7x)^2 - 11^2 = (7x + 11)(7x - 11)$. Dividing by $(7x + 11)$ yields $7x - 11$. The distractor $7x + 11$ selects the wrong factor from the difference of squares factorization, repeating the denominator. The distractor $49x - 11$ fails to recognize that $\\sqrt{49x^2} = 7x$, not $49x$. The distractor $7x^2 - 11$ attempts to divide each term of the numerator separately by $7$ instead of by the binomial $(7x + 11)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20NERFE', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A reservoir initially contains $2{,}340$ gallons of water. A valve releases water at a constant rate of $39$ gallons per minute. After how many minutes will the reservoir contain exactly $507$ gallons?', NULL, $lyceon_json$[{"key":"A","text":"$47$"},{"key":"B","text":"$13$"},{"key":"C","text":"$60$"},{"key":"D","text":"$73$"}]$lyceon_json$::jsonb, 'A', NULL, E'The amount of water after $t$ minutes is $W(t) = 2{,}340 - 39t$. Setting $W(t) = 507$: $2{,}340 - 39t = 507$. Subtracting $2{,}340$ from both sides gives $-39t = -1{,}833$, so $t = 47$. The value $13$ arises from misreading the question and dividing $507$ by $39$ directly, as if $507$ were the amount drained rather than the amount remaining. The value $60$ comes from an equation setup error: dividing $2{,}340$ by $39$, which gives the time to drain the entire reservoir rather than the time to reach $507$ gallons. The value $73$ results from partial reasoning, incorrectly adding $60$ and $13$ together.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20OL8DL', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'Which of the following points $(x, y)$ lies in the solution region of both $5x - 3y \\geq 11$ and $2x + 7y < 19$?', NULL, $lyceon_json$[{"key":"A","text":"$(4, 3)$"},{"key":"B","text":"$(1, -1)$"},{"key":"C","text":"$(5, 1)$"},{"key":"D","text":"$(-1, 2)$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $(5, 1)$: the first inequality gives $5(5) - 3(1) = 22 \\geq 11$, which is true, and the second gives $2(5) + 7(1) = 17 < 19$, which is also true. The point $(4, 3)$ satisfies the first inequality ($5(4) - 3(3) = 11 \\geq 11$, true) but fails the second ($2(4) + 7(3) = 29 < 19$ is false); choosing it reflects checking only the first inequality. The point $(1, -1)$ fails the first inequality ($5(1) - 3(-1) = 8 \\geq 11$ is false), likely resulting from a sign error when evaluating $-3(-1)$. The point $(-1, 2)$ fails the first inequality ($5(-1) - 3(2) = -11 \\geq 11$ is false), reflecting a concept gap about evaluating linear expressions with negative inputs.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20Z3TSW', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f$ is defined by $f(x) = 3(x - 2)^2 + 7$. The graph of $y = f(x) + 4$ has a vertex at which of the following points?', NULL, $lyceon_json$[{"key":"A","text":"$(2, 11)$"},{"key":"B","text":"$(2, 7)$"},{"key":"C","text":"$(6, 7)$"},{"key":"D","text":"$(-2, 11)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The vertex of $f(x) = 3(x - 2)^2 + 7$ is at $(2, 7)$. Adding $4$ to $f(x)$ shifts the graph up by $4$ units, so $y = f(x) + 4 = 3(x - 2)^2 + 11$, and the new vertex is $(2, 11)$. The distractor $(2, 7)$ gives the vertex of the original function $f(x)$ without applying the vertical shift. The distractor $(6, 7)$ adds $4$ to the $x$-coordinate instead of the $y$-coordinate, confusing a vertical shift with a horizontal one. The distractor $(-2, 11)$ correctly shifts the $y$-coordinate by $4$ but negates the $x$-coordinate of the vertex, misreading $(x - 2)$ as having $h = -2$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM216SS74', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A company has $83$ employees. Of these, $31$ work in the engineering department and $52$ work in operations. Among the engineers, $17$ have completed a safety certification, and among the operations staff, $29$ have completed it. If an employee is selected at random from those who have completed the safety certification, what is the probability that the employee works in operations?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{29}{52}$"},{"key":"B","text":"$\\frac{29}{83}$"},{"key":"C","text":"$\\frac{29}{46}$"},{"key":"D","text":"$\\frac{17}{46}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The condition restricts the sample space to employees who have completed the safety certification: $17 + 29 = 46$ total certified employees. Of these, $29$ work in operations, so the conditional probability is $\\frac{29}{46}$. The distractor $\\frac{29}{52}$ incorrectly uses the total number of operations staff as the denominator rather than the total number of certified employees, setting up the conditional probability with the wrong sample space. The distractor $\\frac{29}{83}$ uses the entire company as the denominator, computing the unconditional probability of selecting a certified operations employee rather than the conditional probability given certification. The distractor $\\frac{17}{46}$ correctly identifies the certified-employee total but uses the number of certified engineers in the numerator, answering which department is engineering rather than operations.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM219BLHR', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the system $y = 2x^2 - 9x + k$ and $y = -x + 3$ have exactly one real solution?', NULL, $lyceon_json$[{"key":"A","text":"$-11$"},{"key":"B","text":"$3$"},{"key":"C","text":"$8$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'D', NULL, E'Setting the equations equal: $2x^2 - 9x + k = -x + 3$, which simplifies to $2x^2 - 8x + (k - 3) = 0$. For exactly one real solution, the discriminant must equal zero: $(-8)^2 - 4(2)(k - 3) = 0$. This gives $64 - 8(k - 3) = 0$, so $64 - 8k + 24 = 0$, thus $88 = 8k$ and $k = 11$. The distractor $-11$ results from a sign error when solving for $k$, negating the final answer. The distractor $3$ comes from using only the constant from the linear equation rather than completing the discriminant calculation. The distractor $8$ arises from computing $\\frac{64}{8} = 8$ without accounting for the $+24$ term from distributing $-8(-3)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21RRIBB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'grid_in', E'A pair of headphones originally priced at $\\$130$ is on sale for $30\\%$ off. What is the sale price, in dollars, of the headphones?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '91', ARRAY['91'], E'The discount is $0.30 \\times 130 = \\$39$. The sale price is $130 - 39 = \\$91$. A common error is reporting only the discount amount of $\\$39$ rather than subtracting it from the original price. Another error is subtracting 30 from 130 to get $\\$100$, treating the percentage as a dollar amount.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM227J7RP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A fitness company finds that its customers who use a personal training app at least three times per week have lower body fat percentages than customers who do not use the app. App usage is voluntary. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Using the personal training app at least three times per week causes lower body fat percentages."},{"key":"B","text":"There is an association between frequent app usage and lower body fat percentages."},{"key":"C","text":"The company should require all customers to use the app at least three times per week."},{"key":"D","text":"The study proves that digital fitness tools are more effective than traditional workouts."}]$lyceon_json$::jsonb, 'B', NULL, E'Because app usage is voluntary, this is an observational study. Customers self-selected into frequent app usage, so confounding variables may explain the difference — for example, customers who are already more fitness-motivated may both use the app more often and have lower body fat. The data establish an association but not causation. The causal claim that using the app causes lower body fat is unwarranted without random assignment. The recommendation to require app usage is a policy prescription unsupported by observational data. The claim that the study proves digital fitness tools are more effective overgeneralizes well beyond what a single observational finding about one app at one company can support.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
