INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24AVPZ1', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'A carpenter can spend at most $\\$413$ on lumber for a project. Each board costs $\\$23$, and there is a one-time saw-blade replacement fee of $\\$69$. What is the maximum number of boards the carpenter can purchase within this budget?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '14', ARRAY['14'], E'The inequality is $23b + 69 \\leq 413$. Subtracting 69 from both sides gives $23b \\leq 344$, and dividing by 23 gives $b \\leq 14.956\\ldots$. Since the carpenter can only buy a whole number of boards, the maximum is 14. A common error is forgetting to subtract the saw-blade fee before dividing, which would give $413 / 23 \\approx 17.9$ and a wrong answer of 17. Another error is rounding 14.956 up to 15, which exceeds the budget since $23(15) + 69 = 414 > 413$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM255S6D2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A cone has a radius of $7$ centimeters and a height of $18$ centimeters. The volume of the cone can be written as $k\\pi$ cubic centimeters. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '294', ARRAY['294'], E'The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(7)^2(18) = \\frac{1}{3}\\pi(49)(18) = \\frac{882\\pi}{3} = 294\\pi$ cubic centimeters. Therefore $k = 294$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM256VYZA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'The seven values in a data set are 9, 14, 21, 26, 33, 37, and $k$, where $k$ is a positive integer. If the mean of the data set is 23, what is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21', ARRAY['21'], E'The mean of the seven values is $\\frac{9 + 14 + 21 + 26 + 33 + 37 + k}{7} = 23$. Simplifying: $\\frac{140 + k}{7} = 23$, so $140 + k = 161$, giving $k = 21$. A common error is computing the sum of the known values incorrectly, such as getting 138 instead of 140, yielding $k = 23$. Another error is dividing by 6 instead of 7, forgetting to include $k$ in the count.', NULL, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26ON1RY', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In right triangle $RST$ with the right angle at $T$, $\\sin(R) = \\frac{40}{41}$. If the perimeter of triangle $RST$ is $180$ units, what is the length of the hypotenuse $RS$?', NULL, $lyceon_json$[{"key":"A","text":"$18$"},{"key":"B","text":"$41$"},{"key":"C","text":"$80$"},{"key":"D","text":"$82$"}]$lyceon_json$::jsonb, 'D', NULL, E'Since $\\sin(R) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{ST}{RS} = \\frac{40}{41}$, let $ST = 40k$ and $RS = 41k$. By the Pythagorean theorem, $RT = \\sqrt{(41k)^2 - (40k)^2} = \\sqrt{1681k^2 - 1600k^2} = \\sqrt{81k^2} = 9k$. The perimeter is $9k + 40k + 41k = 90k = 180$, so $k = 2$. The hypotenuse is $RS = 41(2) = 82$. The value $18$ equals $9k = 9(2)$, the length of the shorter leg $RT$, reflecting partial reasoning that reports the wrong side. The value $41$ is the ratio denominator for the hypotenuse before scaling, ignoring the perimeter constraint. The value $80$ equals $40k = 40(2)$, the length of side $ST$, selecting the wrong side of the triangle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26WNQA5', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What is the value of $x$ in the equation $$\\frac{3x + 8}{5} - \\frac{x - 2}{3} = 4\\;?$$', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{13}{2}$"},{"key":"B","text":"$\\frac{23}{2}$"},{"key":"C","text":"$-\\frac{15}{2}$"},{"key":"D","text":"$\\frac{17}{4}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Multiplying every term by $15$ (the LCD of $5$ and $3$) gives $3(3x + 8) - 5(x - 2) = 60$. Expanding: $9x + 24 - 5x + 10 = 60$, so $4x + 34 = 60$. Subtracting $34$ yields $4x = 26$, thus $x = \\frac{26}{4} = \\frac{13}{2}$. The value $\\frac{23}{2}$ results from a sign error when distributing $-5(x - 2)$: writing $-5x - 10$ instead of $-5x + 10$ produces $4x + 14 = 60$, giving $4x = 46$ and $x = \\frac{23}{2}$. The value $-\\frac{15}{2}$ arises from partial reasoning: failing to multiply the right-hand side by the LCD, solving $4x + 34 = 4$ instead of $60$, which gives $4x = -30$ and $x = -\\frac{15}{2}$. The value $\\frac{17}{4}$ comes from an arithmetic slip: multiplying only the first fraction by its LCD factor but not the second, leading to $9x + 24 - x + 2 = 60$, then $8x = 34$ and $x = \\frac{17}{4}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27KBOKR', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A plumber charges a $\\$63$ service call fee plus $\\$41$ per hour of labor. Which function $c(h)$ gives the total cost, in dollars, after $h$ hours of labor?', NULL, $lyceon_json$[{"key":"A","text":"$c(h) = 41h + 63$"},{"key":"B","text":"$c(h) = 63h + 41$"},{"key":"C","text":"$c(h) = 104h$"},{"key":"D","text":"$c(h) = 41h - 63$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is the fixed service fee plus the hourly rate times the number of hours: $c(h) = 41h + 63$. The function $c(h) = 63h + 41$ reflects a concept gap, swapping the roles of the one-time fee and the hourly rate. The function $c(h) = 104h$ comes from an equation setup error, adding $41$ and $63$ into a single rate and treating the total as purely proportional to hours. The function $c(h) = 41h - 63$ arises from a sign error, subtracting the service fee instead of adding it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27LZMK0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'Researchers want to determine whether a new air filtration system reduces respiratory symptoms in office workers. They randomly select $84$ office buildings in a coastal region and randomly assign $42$ buildings to install the new system while $42$ buildings keep their current systems. Over six months, workers in buildings with the new system report significantly fewer respiratory symptoms. A manufacturer''s advertisement states: "New filtration system eliminates respiratory issues in all office environments." Which of the following best evaluates the advertisement''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is supported because the study used random assignment of buildings to treatment groups."},{"key":"B","text":"The claim is supported because workers self-reported significantly fewer symptoms."},{"key":"C","text":"The claim overgeneralizes because the buildings were all in a coastal region, so the results may not apply to all climates, building types, and pollutant exposures."},{"key":"D","text":"The claim is invalid because the researchers should have surveyed workers about their preferences for air filtration instead."}]$lyceon_json$::jsonb, 'C', NULL, E'Although random assignment supports a causal conclusion within this study, all buildings were located in a single coastal region. Climate, building construction standards, indoor pollutant profiles, and worker demographics vary widely across regions, so the results cannot be generalized to all office environments. Additionally, the advertisement claims the system "eliminates" respiratory issues, which overstates even a statistically significant reduction. Citing random assignment alone or the statistical significance of results alone as justification ignores the limitation on generalizability — both support internal validity but do not address external validity. Suggesting a preference survey instead of an experiment reflects a fundamental misunderstanding of study design: surveys measure opinions, while randomized experiments with controlled conditions are required to test causal effects of interventions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27QEBDN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains $9$ red marbles, $14$ blue marbles, and $6$ green marbles. If one marble is selected at random, what is the probability that the marble is green?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{6}{29}$"},{"key":"B","text":"$\\frac{6}{23}$"},{"key":"C","text":"$\\frac{9}{29}$"},{"key":"D","text":"$\\frac{14}{29}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of marbles is $9 + 14 + 6 = 29$. The probability of selecting a green marble is $\\frac{6}{29}$. The distractor $\\frac{6}{23}$ divides the green count by the number of non-green marbles ($9 + 14 = 23$) rather than the total, setting up the fraction incorrectly. The distractor $\\frac{9}{29}$ uses the count of red marbles instead of green marbles, answering the wrong question. The distractor $\\frac{14}{29}$ uses the count of blue marbles instead of green marbles.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2823E0E', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A research firm surveys a random sample of $600$ adults in a county and finds that $44\\%$ favor a new recycling mandate while $56\\%$ oppose it, each with a margin of error of $3.5\\%$. A local news broadcast reports: "County residents decisively oppose the recycling mandate." Which of the following best evaluates the broadcast''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is justified because $56\\%$ opposing exceeds $44\\%$ supporting."},{"key":"B","text":"The claim is justified because a sample of $600$ adults is large enough to produce a definitive result."},{"key":"C","text":"The claim is not justified because the confidence intervals for support ($40.5\\%$ to $47.5\\%$) and opposition ($52.5\\%$ to $59.5\\%$) do not overlap, but the word \"decisively\" overstates the narrowness of the gap."},{"key":"D","text":"The claim is not justified because the survey only measured opinions at one point in time."}]$lyceon_json$::jsonb, 'C', NULL, E'The confidence interval for support is $40.5\\%$ to $47.5\\%$, and for opposition is $52.5\\%$ to $59.5\\%$. These intervals do not overlap, so the data do support a conclusion that more residents oppose the mandate than support it. However, the word "decisively" overstates what the data show — the gap between $44\\%$ and $56\\%$ is $12$ percentage points, but the intervals still place the true values relatively close together, and the characterization of the result as decisive goes beyond the statistical evidence. The claim based solely on $56\\% > 44\\%$ uses partial reasoning — it ignores margin of error entirely. The assertion that $600$ respondents produce a definitive result reflects a conceptual gap — no finite sample eliminates uncertainty, and "definitive" implies certainty that statistics cannot provide. The objection about measuring opinions at one point in time is irrelevant to evaluating whether the statistical claim is supported by the data at hand.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29JIQAI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $420$ commuters in a metropolitan area found that $37\\%$ use public transit, with a margin of error of $5\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $37\\%$ of all commuters in the metropolitan area use public transit."},{"key":"B","text":"Between $32\\%$ and $42\\%$ of the sampled commuters use public transit."},{"key":"C","text":"It is plausible that between $32\\%$ and $42\\%$ of all commuters in the metropolitan area use public transit."},{"key":"D","text":"At least $32\\%$ of all commuters in the metropolitan area use public transit."}]$lyceon_json$::jsonb, 'C', NULL, E'The margin of error creates a confidence interval around the sample statistic: $37\\% \\pm 5\\%$, or $32\\%$ to $42\\%$. This means it is plausible that the true population proportion falls within this range. The claim that exactly $37\\%$ of all commuters use public transit treats the sample statistic as the exact population parameter, ignoring sampling variability. The claim about the sampled commuters misapplies the interval — the margin of error addresses the population parameter, not the sample (the sample result is already known precisely). The claim of at least $32\\%$ captures only the lower bound and ignores that the interval is two-sided, failing to convey the upper bound.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29RSHY2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A recipe requires compound $A$ and compound $B$ in a ratio of $7:3$ by volume. If a technician has 161 milliliters of compound $A$, how many milliliters of compound $B$ are needed to maintain this ratio?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '69', ARRAY['69'], E'Using the ratio $\\frac{7}{3} = \\frac{161}{b}$, cross-multiplying gives $7b = 483$, so $b = 69$ milliliters. A common error is dividing 161 by 3 to get approximately 53.7, confusing which quantity corresponds to which part of the ratio. Another error is computing $\\frac{161}{7} \\times 7 = 161$, accidentally multiplying by the wrong ratio component.', NULL, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
