INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CUC1CD', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points $(2, 9)$ and $(5, 30)$. What is the slope of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'The slope is $m = \\frac{30 - 9}{5 - 2} = \\frac{21}{3} = 7$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DEC4H3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A delivery driver travels the first 78 kilometers at an average speed of 26 kilometers per hour and the remaining 57 kilometers at an average speed of 19 kilometers per hour. Which of the following is closest to the driver''s average speed, in kilometers per hour, for the entire trip?', NULL, $lyceon_json$[{"key":"A","text":"21.5"},{"key":"B","text":"22.5"},{"key":"C","text":"23.5"},{"key":"D","text":"24.5"}]$lyceon_json$::jsonb, 'B', NULL, E'Time for the first segment: $\\frac{78}{26} = 3$ hours. Time for the second segment: $\\frac{57}{19} = 3$ hours. Total distance: $78 + 57 = 135$ km. Total time: $3 + 3 = 6$ hours. Average speed: $\\frac{135}{6} = 22.5$ km/h. The value 21.5 results from an arithmetic slip in computing one of the segment times or the total distance. The value 23.5 comes from a weighted-average approach that incorrectly weights the speeds by distance rather than by time. The value 24.5 results from mistakenly averaging the two speeds as $\\frac{26 + 23}{2} = 24.5$, using $23$ (a number from the problem setup) instead of $19$ for the second rate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E9K81E', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set consists of the values 8, 13, 17, 17, 23, 31. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"15"},{"key":"B","text":"17"},{"key":"C","text":"18.17"},{"key":"D","text":"20"}]$lyceon_json$::jsonb, 'B', NULL, E'The data set has 6 values in order: 8, 13, 17, 17, 23, 31. The median of an even-count data set is the average of the 3rd and 4th values: $\\frac{17 + 17}{2} = 17$. The value 15 comes from averaging the 2nd and 3rd values ($\\frac{13 + 17}{2} = 15$), using incorrect positions. The value 18.17 comes from computing the mean ($\\frac{8 + 13 + 17 + 17 + 23 + 31}{6} \\approx 18.17$) instead of the median. The value 20 comes from averaging the 4th and 5th values ($\\frac{17 + 23}{2} = 20$), misidentifying the middle positions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EJAJY7', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $x$-intercept of the line $4x + 7y = 76$?', NULL, $lyceon_json$[{"key":"A","text":"$(19, 0)$"},{"key":"B","text":"$(0, \\frac{76}{7})$"},{"key":"C","text":"$(-19, 0)$"},{"key":"D","text":"$(7, 0)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The $x$-intercept occurs where $y = 0$. Substituting gives $4x = 76$, so $x = 19$, and the intercept is $(19, 0)$. The point $(0, \\frac{76}{7})$ is the $y$-intercept, indicating the question was misread as asking for the $y$-intercept. The point $(-19, 0)$ comes from a sign error, introducing a negative sign when dividing $76$ by $4$. The point $(7, 0)$ reflects a concept gap, confusing the coefficient of $y$ in the equation with the $x$-intercept value.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EOC2UN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows the relationship between the number of practice sessions per week and a player''s accuracy percentage. The line of best fit has a slope of 3.5. Which of the following is the best interpretation of this slope?', NULL, $lyceon_json$[{"key":"A","text":"For each additional practice session per week, the predicted accuracy increases by 3.5 percentage points."},{"key":"B","text":"A player who attends 3.5 practice sessions per week will have perfect accuracy."},{"key":"C","text":"The accuracy is always 3.5 times the number of practice sessions."},{"key":"D","text":"The baseline accuracy without any practice is 3.5 percentage points."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of a line of best fit represents the predicted change in the dependent variable (accuracy) for each one-unit increase in the independent variable (practice sessions per week). A slope of 3.5 means the predicted accuracy increases by 3.5 percentage points for each additional weekly session. The claim about perfect accuracy at 3.5 sessions confuses the slope with a specific outcome and ignores the y-intercept. The claim that accuracy is always 3.5 times the sessions confuses the slope with direct proportionality, ignoring the y-intercept. The claim about a baseline of 3.5 confuses the slope with the y-intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F1O2LK', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g(x) = (x + 4)^2 - 9$ has a minimum value. What is this minimum value?', NULL, $lyceon_json$[{"key":"A","text":"$-9$"},{"key":"B","text":"$-4$"},{"key":"C","text":"$4$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function $g(x) = (x + 4)^2 - 9$ is in vertex form $g(x) = a(x - h)^2 + k$ with $a = 1 > 0$, $h = -4$, and $k = -9$. Since the parabola opens upward, the vertex $(-4, -9)$ is the minimum point, so the minimum value of $g(x)$ is $-9$. The distractor $-4$ confuses the $x$-coordinate of the vertex with the minimum output value. The distractor $4$ takes the absolute value of $h = -4$, misidentifying it as the minimum of the function. The distractor $9$ takes the absolute value of $k = -9$, applying a sign error to the minimum value.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FBMOLV', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A craft store sells spools of ribbon for $d$ dollars each and packs of buttons for $b$ dollars each. If 5 spools of ribbon and 2 packs of buttons cost $\\$41$, and 3 spools of ribbon and 2 packs of buttons cost $\\$27$, what is the cost, in dollars, of one spool of ribbon?', NULL, $lyceon_json$[{"key":"A","text":"$\\$3$"},{"key":"B","text":"$\\$7$"},{"key":"C","text":"$\\$8$"},{"key":"D","text":"$\\$14$"}]$lyceon_json$::jsonb, 'B', NULL, E'The system is $5d + 2b = 41$ and $3d + 2b = 27$. Subtracting the second from the first eliminates $b$: $2d = 14$, so $d = 7$. One spool of ribbon costs $\\$7$. Substituting back gives $35 + 2b = 41$, so $b = 3$. The distractor $\\$3$ is the price of one pack of buttons, not one spool of ribbon, resulting from answering for the wrong item. The distractor $\\$8$ comes from an arithmetic slip such as computing $5d + 2b = 41$ with $d = 8$ and not verifying with the second equation. The distractor $\\$14$ comes from stopping at $2d = 14$ without dividing by 2, confusing the intermediate result with the final answer.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FM1N87', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 - 14x + 6y + 9 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$7$"},{"key":"C","text":"$\\sqrt{40}$"},{"key":"D","text":"$49$"}]$lyceon_json$::jsonb, 'B', NULL, E'Completing the square: $(x^2 - 14x + 49) + (y^2 + 6y + 9) = -9 + 49 + 9$, which gives $(x - 7)^2 + (y + 3)^2 = 49$. The radius is $r = \\sqrt{49} = 7$. The value $3$ comes from taking the square root of the constant term $9$ in the original equation ($\\sqrt{9} = 3$) without completing the square, misreading the equation structure. The value $\\sqrt{40}$ arises from an arithmetic slip in the completing-the-square computation, such as computing $-9 + 49 = 40$ and forgetting to add the second completing term $+9$. The value $49$ gives $r^2$ rather than $r$, a concept gap about the final step of extracting the radius from standard form.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FRGZG5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal. One of the co-interior (same-side interior) angles measures $(4x + 7)^\\circ$ and the other measures $(6x - 27)^\\circ$. What is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$15$"},{"key":"B","text":"$17$"},{"key":"C","text":"$20$"},{"key":"D","text":"$75$"}]$lyceon_json$::jsonb, 'C', NULL, E'Co-interior angles formed by parallel lines and a transversal are supplementary, so they sum to $180^\\circ$: $(4x + 7) + (6x - 27) = 180$. Combining like terms gives $10x - 20 = 180$, so $10x = 200$ and $x = 20$. The value $15$ results from an arithmetic slip such as computing $10x = 150$ instead of $10x = 200$. The value $17$ comes from treating the angles as equal rather than supplementary (setting $4x + 7 = 6x - 27$, giving $2x = 34$ and $x = 17$), a concept gap about the co-interior angle relationship. The value $75$ is the result of substituting $x = 17$ into $4(17) + 7 = 75$, compounding the conceptual error by reporting the angle measure instead of the value of $x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FZTIH6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'grid_in', E'A line of best fit for a data set is given by $y = 4.7x + 13$. Using this model, what is the predicted value of $y$ when $x = 6$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '41.2', ARRAY['206/5', '41.2'], E'Substituting $x = 6$: $y = 4.7(6) + 13 = 28.2 + 13 = 41.2$. A common error is computing $4.7 \\times 6$ as $28.2$ but then adding 1.3 instead of 13, getting 29.5. Another error is forgetting the y-intercept entirely and reporting only $4.7 \\times 6 = 28.2$.', NULL, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GOOVZG', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $9(2x + 5) - 13x$?', NULL, $lyceon_json$[{"key":"A","text":"$5x + 5$"},{"key":"B","text":"$5x + 45$"},{"key":"C","text":"$31x + 45$"},{"key":"D","text":"$5x - 45$"}]$lyceon_json$::jsonb, 'B', NULL, E'Distributing the $9$ gives $9(2x + 5) - 13x = 18x + 45 - 13x = 5x + 45$. The distractor $5x + 5$ correctly combines $18x - 13x = 5x$ but fails to distribute the $9$ to $5$, leaving the constant as $5$ instead of $45$. The distractor $31x + 45$ adds $18x + 13x = 31x$ instead of subtracting, treating the $-13x$ as $+13x$. The distractor $5x - 45$ correctly finds $5x$ but applies a sign error to the constant, writing $-45$ instead of $+45$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HN6SS4', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $3x^2 - 17x + 10 = 0$, what is the larger value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Using the quadratic formula: $x = \\frac{17 \\pm \\sqrt{(-17)^2 - 4(3)(10)}}{2(3)} = \\frac{17 \\pm \\sqrt{289 - 120}}{6} = \\frac{17 \\pm \\sqrt{169}}{6} = \\frac{17 \\pm 13}{6}$. This gives $x = \\frac{30}{6} = 5$ or $x = \\frac{4}{6} = \\frac{2}{3}$. The larger value is $5$. This can be verified by factoring: $3x^2 - 17x + 10 = (3x - 2)(x - 5) = 0$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I3YL4S', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $23$ units. What is the circumference of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$11.5\\pi$"},{"key":"B","text":"$23\\pi$"},{"key":"C","text":"$46\\pi$"},{"key":"D","text":"$529\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The circumference of a circle is $C = 2\\pi r = 2\\pi(23) = 46\\pi$. The value $11.5\\pi$ results from dividing the radius by $2$ rather than multiplying, an equation setup error. The value $23\\pi$ comes from computing $\\pi r$ instead of $2\\pi r$, omitting the factor of $2$ and reflecting partial reasoning. The value $529\\pi$ uses the area formula $\\pi r^2 = \\pi(23)^2 = 529\\pi$ instead of the circumference formula, a concept gap confusing area with circumference.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KJM63S', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A biologist collects data on the dosage (in milligrams) and the reduction in symptom score for 40 patients. The line of best fit is $r = 1.4d - 3$, where $r$ is the predicted reduction in symptom score and $d$ is the dosage in milligrams. A patient receiving a dosage of 11 milligrams has an actual reduction in symptom score of 14. What is the residual for this observation?', NULL, $lyceon_json$[{"key":"A","text":"$1.6$"},{"key":"B","text":"$-1.6$"},{"key":"C","text":"$12.4$"},{"key":"D","text":"$14$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted reduction at a dosage of 11 is $r = 1.4(11) - 3 = 15.4 - 3 = 12.4$. The residual is the actual value minus the predicted value: $14 - 12.4 = 1.6$. The value $-1.6$ results from reversing the subtraction order, computing predicted minus actual instead of actual minus predicted. The value 12.4 is the predicted value itself, not the residual. The value 14 is the actual observed value, not the difference between actual and predicted.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M9XJPB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A coach records the following race times, in seconds, for 8 runners: 47, 51, 54, 58, 62, 65, 69, 74. If the time of 74 seconds is removed from the data set, which of the following correctly describes the change in the mean and the range?', NULL, $lyceon_json$[{"key":"A","text":"Both the mean and the range decrease."},{"key":"B","text":"The mean decreases and the range stays the same."},{"key":"C","text":"The mean stays the same and the range decreases."},{"key":"D","text":"The mean decreases and the range increases."}]$lyceon_json$::jsonb, 'A', NULL, E'Original 8 times sum to $47 + 51 + 54 + 58 + 62 + 65 + 69 + 74 = 480$. Original mean: $\\frac{480}{8} = 60$. Original range: $74 - 47 = 27$. After removing 74, the 7 remaining times sum to 406. New mean: $\\frac{406}{7} = 58$, which is lower. New range: $69 - 47 = 22$, which is also lower. So both the mean and the range decrease. The claim that the range stays the same is wrong because the maximum value was removed, reducing the range from 27 to 22. The claim that the mean stays the same ignores that the removed value is above the original mean. The claim that the range increases contradicts the removal of the maximum value.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 95, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MAT4RZ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the product of the solutions to the equation $x^2 + 3x - 40 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$-40$"},{"key":"B","text":"$40$"},{"key":"C","text":"$-3$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factoring gives $x^2 + 3x - 40 = (x + 8)(x - 5) = 0$, so $x = -8$ or $x = 5$. The product of the solutions is $(-8)(5) = -40$. By Vieta''s formulas, the product of the roots of $x^2 + bx + c = 0$ equals $c$, which is $-40$. The distractor $40$ applies a sign error, taking the absolute value of the constant term instead of $-40$. The distractor $-3$ confuses the product of the roots with the negation of the coefficient of $x$, which gives the sum of the roots, not the product. The distractor $3$ takes the coefficient of $x$ directly as though it were the product.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MUHWNK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A factory produces 93 bolts every 3 minutes. At this rate, how many bolts does the factory produce in 17 minutes?', NULL, $lyceon_json$[{"key":"A","text":"496"},{"key":"B","text":"527"},{"key":"C","text":"531"},{"key":"D","text":"558"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{93}{3} = 31$ bolts per minute. In 17 minutes: $31 \\times 17 = 527$ bolts. The value 496 results from an arithmetic slip such as computing $31 \\times 16$ instead of $31 \\times 17$. The value 531 comes from setting up the proportion incorrectly, for example adding 93 and 17 before multiplying. The value 558 arises from using $\\frac{93}{3} = 31$ but then multiplying $31 \\times 18$, misreading the number of minutes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MWNZVG', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'What value of $x$ satisfies the equation $11x + 37 = 158$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'Subtracting $37$ from both sides gives $11x = 121$. Dividing both sides by $11$ yields $x = 11$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MWP77Z', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the solution to the equation $4(3x - 5) = 2x + 30$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{2}$"},{"key":"B","text":"$5$"},{"key":"C","text":"$-5$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'B', NULL, E'Distributing on the left side gives $12x - 20 = 2x + 30$. Subtracting $2x$ from both sides yields $10x - 20 = 30$. Adding $20$ to both sides gives $10x = 50$, so $x = 5$. The value $\\frac{7}{2}$ results from an arithmetic slip: failing to distribute $4$ to the $-5$ term, writing $12x - 5 = 2x + 30$, which leads to $10x = 35$ and $x = \\frac{7}{2}$. The value $-5$ comes from a sign error when dividing $50$ by $10$, incorrectly attaching a negative sign to the result. The value $3$ arises from partial reasoning, such as incorrectly simplifying $12x = 2x + 30$ (dropping the $-20$ entirely) to get $10x = 30$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MYYAN5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A rectangular swimming pool is $19$ meters long and $11$ meters wide. A uniform tile border of width $3$ meters surrounds the pool on all sides. What is the area, in square meters, of the tile border alone?', NULL, $lyceon_json$[{"key":"A","text":"$209$"},{"key":"B","text":"$216$"},{"key":"C","text":"$228$"},{"key":"D","text":"$425$"}]$lyceon_json$::jsonb, 'B', NULL, E'The outer rectangle, including the border, has length $19 + 2(3) = 25$ meters and width $11 + 2(3) = 17$ meters, giving an outer area of $25 \\times 17 = 425$ square meters. The pool area is $19 \\times 11 = 209$ square meters. The border area is $425 - 209 = 216$ square meters. The value $209$ is the area of the pool itself rather than the border, a misread of what the question asks. The value $228$ results from an arithmetic slip, such as computing the outer area as $25 \\times 17 = 437$ by error and then subtracting $209$ to get $228$. The value $425$ is the total outer area without subtracting the pool, reflecting partial reasoning that stops before the final subtraction step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N37CTL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'In a company survey, $42\\%$ of respondents preferred option $X$ and $31\\%$ preferred option $Y$. The remaining respondents were split equally among three other options. If option $X$ received 378 votes, how many votes did each of the three other options receive?', NULL, $lyceon_json$[{"key":"A","text":"$279$"},{"key":"B","text":"$243$"},{"key":"C","text":"$81$"},{"key":"D","text":"$93$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since option $X$ received $42\\%$ of the votes and got 378 votes, the total number of votes is $378 \\div 0.42 = 900$. Option $Y$ received $31\\%$ of 900, which is 279 votes. The remaining percentage is $100\\% - 42\\% - 31\\% = 27\\%$, so $0.27 \\times 900 = 243$ votes were split equally among three options, giving each $243 \\div 3 = 81$ votes. The distractor 279 is the number of votes option $Y$ received, not one of the three other options. The distractor 243 results from computing the total remaining votes but forgetting to divide by 3. The distractor 93 results from mistakenly using candidate Y''s percentage ($31\\%$) as the remaining percentage instead of computing $100\\% - 42\\% - 31\\% = 27\\%$, giving $0.31 \\times 900 / 3 = 93$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N4MJXG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A university polls a random sample of $250$ students and finds that $71\\%$ are satisfied with campus dining. A follow-up poll of a random sample of $1{,}000$ students at the same university finds that $68\\%$ are satisfied, with a smaller margin of error. Which of the following best explains why the follow-up poll has a smaller margin of error?', NULL, $lyceon_json$[{"key":"A","text":"The follow-up poll found a lower satisfaction rate, which decreases the margin of error."},{"key":"B","text":"The follow-up poll surveyed four times as many students, which decreases the margin of error."},{"key":"C","text":"The follow-up poll was conducted later in the semester, when opinions had stabilized."},{"key":"D","text":"The follow-up poll asked a clearer question, which reduced variability in responses."}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error is inversely related to the square root of the sample size. The follow-up poll sampled $1{,}000$ students compared to $250$, a fourfold increase, so its margin of error is approximately halved. The claim that a lower satisfaction rate reduces the margin of error conflates the value of the statistic with sampling precision — while the proportion does have a minor effect, the dominant factor is the much larger sample size. The suggestion about timing introduces an irrelevant factor unrelated to the statistical definition of margin of error. The claim about a clearer question is unsubstantiated and does not address how margin of error is calculated from sample size.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NYU4OG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $PQR$, side $QR$ is extended through $R$ to point $S$. The exterior angle $PRS$ measures $(11m - 5)^\\circ$, angle $P$ measures $(6m + 7)^\\circ$, and angle $Q$ measures $(4m + 1)^\\circ$. What is the measure, in degrees, of the exterior angle $PRS$?', NULL, $lyceon_json$[{"key":"A","text":"$13^\\circ$"},{"key":"B","text":"$53^\\circ$"},{"key":"C","text":"$85^\\circ$"},{"key":"D","text":"$138^\\circ$"}]$lyceon_json$::jsonb, 'D', NULL, E'By the exterior angle theorem, the exterior angle equals the sum of the two non-adjacent interior angles: $(11m - 5) = (6m + 7) + (4m + 1)$. The right side simplifies to $10m + 8$. So $11m - 5 = 10m + 8$, giving $m = 13$. The exterior angle is $11(13) - 5 = 143 - 5 = 138^\\circ$. Verification: angle $P = 6(13) + 7 = 85^\\circ$ and angle $Q = 4(13) + 1 = 53^\\circ$, and $85 + 53 = 138^\\circ$. The value $13^\\circ$ is just the value of $m$, not the angle measure, reflecting partial reasoning that stops at the intermediate variable. The value $53^\\circ$ is the measure of angle $Q$, not the exterior angle, answering the wrong angle. The value $85^\\circ$ is the measure of angle $P$, again selecting the wrong angle from the problem.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PUOJ5U', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one leg has length $20$ and the hypotenuse has length $29$. What is the length of the other leg?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$21$"},{"key":"C","text":"$49$"},{"key":"D","text":"$15$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using the Pythagorean theorem, $a^2 + b^2 = c^2$, where $a = 20$ and $c = 29$: $20^2 + b^2 = 29^2$, so $400 + b^2 = 841$, giving $b^2 = 441$ and $b = 21$. The distractor $9$ results from subtracting the legs ($29 - 20 = 9$) instead of using the Pythagorean theorem. The distractor $49$ results from adding the given values ($20 + 29 = 49$) rather than applying the correct formula. The distractor $15$ results from a computational error such as miscalculating $\\sqrt{441}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QPN78C', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $\\ell$ is parallel to the line $7x + 2y = 18$ and passes through the point $(4, -3)$. What is the $y$-intercept of line $\\ell$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, 11)$"},{"key":"B","text":"$(0, 17)$"},{"key":"C","text":"$(0, 9)$"},{"key":"D","text":"$(0, -11)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rearranging $7x + 2y = 18$ gives $y = -\\frac{7}{2}x + 9$, so the slope is $-\\frac{7}{2}$. A parallel line has the same slope. Using point-slope form with $(4, -3)$: $y + 3 = -\\frac{7}{2}(x - 4)$, which gives $y = -\\frac{7}{2}x + 14 - 3 = -\\frac{7}{2}x + 11$. The $y$-intercept is $(0, 11)$. The intercept $(0, 17)$ results from a sign error: computing $14 + 3$ instead of $14 - 3$ when simplifying the constant. The intercept $(0, 9)$ reflects a concept gap, simply using the $y$-intercept of the original line without accounting for the new point. The intercept $(0, -11)$ comes from an equation setup error, negating the entire intercept value.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RCFPQG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In right triangle $JKL$ with the right angle at $L$, $\\sin(J) = \\frac{7}{25}$. What is $\\cos(J)$? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '24/25', ARRAY['24/25', '0.96', '.96'], E'Since $\\sin(J) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{7}{25}$, the side opposite angle $J$ (which is $KL$) has length $7$ and the hypotenuse $JK$ has length $25$. By the Pythagorean theorem, the adjacent side $JL = \\sqrt{25^2 - 7^2} = \\sqrt{625 - 49} = \\sqrt{576} = 24$. Therefore $\\cos(J) = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{24}{25}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RD2VKC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'In the $xy$-plane, a circle has center $(-5, 7)$ and passes through the point $(3, 1)$. A chord of the circle has its midpoint at $(-5, 1)$. What is the length of this chord?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$8$"},{"key":"C","text":"$12$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'D', NULL, E'First, find the radius: $r = \\sqrt{(3 - (-5))^2 + (1 - 7)^2} = \\sqrt{64 + 36} = \\sqrt{100} = 10$. The midpoint of the chord is $(-5, 1)$. The distance from the center $(-5, 7)$ to the midpoint $(-5, 1)$ is $|7 - 1| = 6$. A line from the center to the midpoint of a chord is perpendicular to the chord, forming a right triangle with the radius as hypotenuse and the perpendicular distance as one leg. The half-chord length is $\\sqrt{10^2 - 6^2} = \\sqrt{100 - 36} = \\sqrt{64} = 8$. The full chord length is $2 \\times 8 = 16$. The value $6$ is the distance from the center to the chord midpoint, not the chord length, reflecting partial reasoning that reports the wrong measurement. The value $8$ is the half-chord length, forgetting to double it to obtain the full chord. The value $12$ comes from doubling the perpendicular distance ($2 \\times 6 = 12$) rather than doubling the half-chord, a concept gap about which segment to double.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RDBQBF', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'If $\\frac{10x^2 + 29x - 21}{2x + 7} = ax + b$ for all $x \\neq -\\frac{7}{2}$, what is the value of $a + b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'Factor the numerator $10x^2 + 29x - 21$. We seek two numbers with product $10 \\times (-21) = -210$ and sum $29$. Those numbers are $35$ and $-6$. Rewriting: $10x^2 + 35x - 6x - 21 = 5x(2x + 7) - 3(2x + 7) = (5x - 3)(2x + 7)$. Dividing by $(2x + 7)$ gives $5x - 3$, so $a = 5$ and $b = -3$. Therefore $a + b = 5 + (-3) = 2$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UYJTTK', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following values of $x$ satisfies the inequality $9x - 17 < 28$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$7$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding 17 to both sides gives $9x < 45$, and dividing both sides by 9 gives $x < 5$. Among the choices, only $3$ is strictly less than 5, since $9(3) - 17 = 10 < 28$. The value $5$ yields $9(5) - 17 = 28$, which equals 28 but is not strictly less than 28, reflecting confusion between $<$ and $\\leq$. The value $7$ gives $9(7) - 17 = 46$, which exceeds 28 and reflects a general concept gap about the direction of the inequality. The value $9$ gives $9(9) - 17 = 64$, which greatly exceeds 28, possibly resulting from an arithmetic slip when solving.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VO1VQI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A bag contains $7$ black tokens and $11$ white tokens. Two tokens are drawn one at a time without replacement. Given that the first token drawn is black, what is the probability that the second token drawn is also black?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{18}$"},{"key":"B","text":"$\\frac{6}{18}$"},{"key":"C","text":"$\\frac{6}{17}$"},{"key":"D","text":"$\\frac{7}{17}$"}]$lyceon_json$::jsonb, 'C', NULL, E'After one black token is drawn, $17$ tokens remain: $6$ black and $11$ white. The conditional probability that the second token is also black is $\\frac{6}{17}$. The distractor $\\frac{7}{18}$ uses the original counts ($7$ black out of $18$ total), failing to account for the without-replacement condition. The distractor $\\frac{6}{18}$ reduces the black count to $6$ but keeps the total at $18$, an arithmetic error in applying the without-replacement adjustment. The distractor $\\frac{7}{17}$ correctly reduces the total to $17$ but keeps the black count at $7$, failing to remove the drawn black token from the numerator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X06VPW', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $q$ is defined by $q(x) = 4x^3 - 11x^2 + 2$. Which of the following correctly describes the end behavior of $q(x)$?', NULL, $lyceon_json$[{"key":"A","text":"As $x \\to \\infty$, $q(x) \\to \\infty$; as $x \\to -\\infty$, $q(x) \\to -\\infty$"},{"key":"B","text":"As $x \\to \\infty$, $q(x) \\to -\\infty$; as $x \\to -\\infty$, $q(x) \\to \\infty$"},{"key":"C","text":"As $x \\to \\infty$, $q(x) \\to \\infty$; as $x \\to -\\infty$, $q(x) \\to \\infty$"},{"key":"D","text":"As $x \\to \\infty$, $q(x) \\to 2$; as $x \\to -\\infty$, $q(x) \\to 2$"}]$lyceon_json$::jsonb, 'A', NULL, E'The leading term of $q(x) = 4x^3 - 11x^2 + 2$ is $4x^3$. For an odd-degree polynomial with a positive leading coefficient, as $x \\to \\infty$ the function goes to $\\infty$, and as $x \\to -\\infty$ the function goes to $-\\infty$. The distractor reversing these directions describes the end behavior of $-x^3$, applying a sign error to the leading coefficient. The distractor stating both ends go to $\\infty$ describes even-degree positive-leading-coefficient behavior, confusing odd-degree and even-degree end behavior. The distractor stating both ends approach $2$ treats the constant term as a horizontal asymptote, which does not apply to polynomial functions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XN74HN', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'The function $f$ is defined by $f(x) = -7x + 89$. For what value of $x$ does $f(x) = 19$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10', ARRAY['10'], E'Setting $f(x) = 19$ gives $-7x + 89 = 19$. Subtracting $89$ from both sides yields $-7x = -70$. Dividing both sides by $-7$ gives $x = 10$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YALNR5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular poster has a length of $23$ inches and a width of $17$ inches. What is the area of the poster, in square inches?', NULL, $lyceon_json$[{"key":"A","text":"$80$"},{"key":"B","text":"$391$"},{"key":"C","text":"$400$"},{"key":"D","text":"$782$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a rectangle is length times width: $A = 23 \\times 17 = 391$ square inches. The value $80$ is the perimeter, $2(23 + 17) = 2(40) = 80$, confusing perimeter with area. The value $400$ arises from rounding $23$ to $20$ and $17$ to $20$, computing $20 \\times 20 = 400$, an arithmetic slip from approximate calculation. The value $782$ results from doubling the correct area ($2 \\times 391 = 782$), perhaps applying the perimeter multiplier to the area formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YYKNUQ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $DEF$, the measure of angle $D$ is $37^\\circ$ and the measure of angle $F$ is $89^\\circ$. What is the measure, in degrees, of angle $E$?', NULL, $lyceon_json$[{"key":"A","text":"$52^\\circ$"},{"key":"B","text":"$54^\\circ$"},{"key":"C","text":"$91^\\circ$"},{"key":"D","text":"$126^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of any triangle is $180^\\circ$. Therefore, angle $E = 180^\\circ - 37^\\circ - 89^\\circ = 54^\\circ$. The value $52^\\circ$ results from a subtraction error such as computing $180 - 89 = 91$ correctly but then subtracting $39$ instead of $37$. The value $91^\\circ$ comes from subtracting only angle $F$ from $180^\\circ$ ($180 - 89 = 91$) and stopping, reflecting incomplete reasoning. The value $126^\\circ$ results from adding the two given angles ($37 + 89 = 126$) and treating their sum as the missing angle rather than subtracting from $180$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z3J550', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A store decreases the price of an item by $20\\%$. One month later, the store increases the reduced price by $20\\%$. If the original price of the item was $\\$95$, what is the final price after both changes?', NULL, $lyceon_json$[{"key":"A","text":"$\\$91.20$"},{"key":"B","text":"$\\$76.00$"},{"key":"C","text":"$\\$95.00$"},{"key":"D","text":"$\\$99.00$"}]$lyceon_json$::jsonb, 'A', NULL, E'After a $20\\%$ decrease, the price becomes $95 \\times 0.80 = \\$76$. After a $20\\%$ increase on $\\$76$, the price becomes $76 \\times 1.20 = \\$91.20$. The value $\\$76$ results from computing only the first change and ignoring the second. The value $\\$95$ comes from the misconception that a $20\\%$ decrease followed by a $20\\%$ increase returns to the original price. The value $\\$99$ results from an arithmetic slip such as computing $76 \\times 1.30$ instead of $76 \\times 1.20$ or adding a flat $\\$19$ to $\\$76$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20E5663', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the passage, "marked" most nearly means', E'The geologist noted that the transition from sandstone to shale was marked by a thin band of iron-rich sediment, visible as a rust-colored stripe running horizontally across the exposed cliff face near the river.', $lyceon_json$[{"key":"A","text":"graded"},{"key":"B","text":"indicated"},{"key":"C","text":"stained"},{"key":"D","text":"marketed"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes a geological transition that was signaled or shown by a visible band of sediment. "Indicated" correctly captures the sense of something being made apparent or pointed out by a distinguishing feature. "Graded" means to assign a rank or score to something, which is incoherent when describing a natural sediment layer signaling a geological boundary. "Stained" means to discolor with a dye or pigment, but the passage describes the band as identifying the transition, not physically discoloring it. "Marketed" means to promote or advertise a product for sale, which has no connection to geological features revealing a boundary between rock types.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20MBALZ', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the passage, "elastic" most nearly means', E'Historian Priya Raghavan argues that the concept of citizenship in the early Roman Republic was remarkably elastic: it could be stretched to incorporate conquered Italic peoples when military alliance demanded it, yet contracted to exclude freedmen from certain voting assemblies when patrician families perceived a threat to their political dominance.', $lyceon_json$[{"key":"A","text":"rubbery"},{"key":"B","text":"adaptable"},{"key":"C","text":"resilient"},{"key":"D","text":"permanent"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes Roman citizenship as a concept that could be expanded or narrowed depending on political circumstances — incorporating new groups when useful and excluding others when convenient. "Adaptable" correctly captures this sense of being flexible and responsive to changing conditions. "Rubbery" refers to the physical texture or consistency of rubber, which is incoherent when describing a political concept''s ability to shift boundaries. "Resilient" means able to recover quickly from difficulties, but the passage is not describing citizenship bouncing back from setbacks; it is describing citizenship being deliberately reshaped to serve different political purposes. "Permanent" means lasting indefinitely without change, which directly contradicts the passage''s depiction of citizenship as a concept that expanded and contracted.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22JOORP', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the lead conservator nor the three assistant restorers who examined the seventeenth-century altarpiece _____ able to determine whether the cracking in the lower panels resulted from fluctuations in humidity or from the original application of an incompatible varnish layer.', $lyceon_json$[{"key":"A","text":"was"},{"key":"B","text":"were"},{"key":"C","text":"is"},{"key":"D","text":"has been"}]$lyceon_json$::jsonb, 'B', NULL, E'In a "neither...nor" construction, the verb agrees with the subject closest to it — here, "the three assistant restorers," which is plural. The sentence is set in the past tense, as indicated by "examined" and "resulted." The plural past-tense "were" correctly agrees with "restorers" and maintains tense consistency. The singular past-tense "was" would agree with the first element ("the lead conservator") but not with the nearer plural subject, violating the proximity agreement rule for "neither...nor" constructions. The singular present-tense "is" fails on both number agreement with the nearer subject and tense consistency. The singular present-perfect "has been" also fails on number agreement and introduces a tense shift away from the established past-tense frame.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
