INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25IMN5I', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The titanium alloy that materials scientist Ingrid Halvorsen developed for use in deep-sea drilling _____ can withstand pressures exceeding four hundred atmospheres without exhibiting measurable fatigue, a property that has attracted interest from both petroleum engineers and oceanographic instrument manufacturers.', $lyceon_json$[{"key":"A","text":"equipment—which resists corrosion in sulfide-rich environments—"},{"key":"B","text":"equipment, which resists corrosion in sulfide-rich environments"},{"key":"C","text":"equipment which resists corrosion in sulfide-rich environments,"},{"key":"D","text":"equipment which resists corrosion in sulfide-rich environments"}]$lyceon_json$::jsonb, 'A', NULL, E'The clause "which resists corrosion in sulfide-rich environments" is a nonrestrictive relative clause providing additional information about the alloy. Because this clause is embedded mid-sentence — interrupting the subject ("The titanium alloy... equipment") and its predicate ("can withstand") — it must be set off by paired punctuation on both sides. Em dashes on both sides correctly bracket the interrupting clause. Using a comma before the clause but no punctuation after it ("equipment, which resists corrosion in sulfide-rich environments can") leaves the nonrestrictive clause unclosed, making the sentence boundary ambiguous and merging the parenthetical into the predicate. Omitting the comma before "which" and placing one only after "environments" ("equipment which resists corrosion in sulfide-rich environments, can") incorrectly treats the clause as restrictive on the left while closing it as nonrestrictive on the right, producing mismatched boundaries. Omitting all setting-off punctuation ("equipment which resists corrosion in sulfide-rich environments can") makes the nonrestrictive clause appear restrictive and fuses it into the surrounding sentence without the necessary pauses, obscuring the sentence''s grammatical structure.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 115, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26SU28E', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Sociologist Arjun Mehta has studied the impact of remote work policies on urban housing markets across eleven midsize cities in the northeastern United States. His data show that between 2020 and 2023, median rents in these cities declined by an average of 9%, as many white-collar workers relocated to suburban or rural areas. _______ in three of those cities -- Hartford, Providence, and Albany -- median rents actually increased by 4% to 7% during the same period, a pattern Mehta attributes to an influx of younger workers drawn by lower costs relative to nearby metropolitan hubs like New York and Boston.', $lyceon_json$[{"key":"A","text":"Consequently,"},{"key":"B","text":"Similarly,"},{"key":"C","text":"That said,"},{"key":"D","text":"In other words,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence before the blank presents a general trend -- a 9% average decline in median rents across eleven cities. The sentence after the blank introduces an exception: three specific cities where rents actually rose during the same period. "That said," correctly signals a qualification or partial counterpoint to the preceding generalization. "Consequently," implies the rent increases in those three cities were caused by the overall decline, but the passage presents them as exceptions to the trend, not effects of it. "Similarly," suggests the three cities followed the same pattern, which directly contradicts the fact that their rents increased rather than declined. "In other words," would restate the previous claim in different terms, but the sentence introduces new, contrasting information rather than rephrasing the general decline.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28ACQSJ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The fruit of the durian tree (Durio zibethinus) emits a pungent odor that most humans find extremely unpleasant, yet the fruit is a preferred food source for several large mammal species in Southeast Asian rainforests, including Asian elephants and sun bears. Ecologists have noted that these animals can detect fallen durian fruit from distances exceeding two kilometers, even in dense forest where visual cues are unavailable. This observation suggests that the durian''s strong odor ________', $lyceon_json$[{"key":"A","text":"functions as a long-range chemical signal that attracts the large mammals responsible for dispersing the tree's seeds."},{"key":"B","text":"developed as a defense mechanism to prevent insects from consuming the fruit before it ripens."},{"key":"C","text":"is the result of a recent genetic mutation that has spread through durian populations only within the last century."},{"key":"D","text":"makes the fruit toxic to small mammals, ensuring that only large animals consume it."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that large mammals detect durian fruit by smell from great distances in dense forest, and that these animals are preferred consumers of the fruit. The logical inference is that the odor serves as a long-range attractant for seed-dispersing animals. The option about insect defense introduces a purpose not suggested by the passage, which focuses on attracting large mammals rather than repelling insects. The option about a recent genetic mutation fabricates a timeframe and mechanism with no textual basis. The option about toxicity to small mammals introduces a harmful effect the passage never mentions — the text discusses attraction, not deterrence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28GK4VB', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the passage?', E'Traditional beekeeping manuals advise placing hives in sheltered, south-facing locations to maximize sun exposure during winter months. Entomologist Keiko Furukawa, however, observed that feral honeybee colonies in the Pacific Northwest frequently establish nests in north-facing tree cavities with minimal direct sunlight. In a controlled study of 67 managed colonies, Furukawa found that hives placed in north-facing positions experienced lower rates of varroa mite infestation than south-facing hives, possibly because the cooler microclimate inhibited mite reproduction cycles.', $lyceon_json$[{"key":"A","text":"It presents a conventional practice, introduces an observation that contradicts it, and then offers research that supports the alternative approach"},{"key":"B","text":"It traces the historical evolution of beekeeping techniques from ancient to modern methods"},{"key":"C","text":"It describes two competing theories about honeybee behavior and declares one definitively superior"},{"key":"D","text":"It summarizes Furukawa's career achievements in the field of entomology"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage follows a three-part structure: it states the traditional advice about south-facing hive placement, introduces Furukawa''s contradictory observation about feral colonies, and then presents her controlled study showing a potential advantage of north-facing placement. Tracing the historical evolution of beekeeping mischaracterizes the scope — the passage contrasts one conventional practice with one researcher''s findings, not a timeline of techniques. Describing two competing theories and declaring one superior overstates the passage''s conclusion; Furukawa''s findings are presented as suggestive rather than definitive, and the passage does not dismiss traditional placement outright. Summarizing Furukawa''s career achievements misidentifies the focus, which is a single observation and study, not a biographical overview.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28QNYNS', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Neuroscientist Elina Korhonen has proposed that the consolidation of procedural memories during sleep relies on a two-phase mechanism: slow-wave oscillations first reactivate motor sequences encoded during waking practice, and subsequent REM-phase bursts then prune redundant neural pathways to stabilize the refined motor program. Critics have noted that Korhonen''s model predicts a specific temporal ordering -- slow-wave reactivation must precede REM pruning -- yet polysomnographic data from her own 2021 study show that in 29% of recorded sleep cycles, REM bursts occurred before or simultaneously with slow-wave reactivation events. Korhonen has responded that those atypical cycles corresponded to sessions in which participants had already reached a performance plateau during waking practice, meaning the motor program required minimal pruning. _______ she argues that her two-phase model applies specifically to the consolidation of novel, not yet stabilized, motor sequences, and that plateau-phase sleep cycles represent a distinct consolidation regime outside the model''s intended scope.', $lyceon_json$[{"key":"A","text":"Put differently,"},{"key":"B","text":"Nonetheless,"},{"key":"C","text":"In particular,"},{"key":"D","text":"Likewise,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence before the blank presents Korhonen''s response to the critics: the atypical cycles involved participants who had already plateaued. The sentence after the blank restates and clarifies this defense in more precise theoretical terms -- her model applies to novel motor sequences, and plateau-phase cycles fall outside its scope. "Put differently," correctly signals that the subsequent sentence is a reformulation of the same argument in more explicit language. "Nonetheless," implies the subsequent sentence persists despite an obstacle presented in the preceding sentence, but both sentences are parts of the same defense rather than a concession followed by a counterpoint. "In particular," would narrow a general claim to a specific instance, but the subsequent sentence broadens the defense into a general scope limitation rather than specifying a detail. "Likewise," implies a parallel between two separate observations, but the subsequent sentence restates the same point rather than introducing a separate, analogous one.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29MSOW6', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which quotation from a materials scientist, if true, would most directly support the claim that the polymer coating improves battery performance under cold conditions?', E'Engineers at a Finnish startup have developed a polymer coating for lithium-ion battery cathodes that they claim significantly improves energy output in sub-zero temperatures. Standard lithium-ion batteries lose up to 40% of their capacity at minus 20 degrees Celsius because lithium ions move more slowly through the electrolyte in cold conditions. The startup''s coating, made from a proprietary polyether compound, is designed to reduce the activation energy required for lithium ions to transfer between the electrolyte and the cathode surface, theoretically maintaining ion flow rates closer to room-temperature levels even in extreme cold.', $lyceon_json$[{"key":"A","text":"\"Batteries treated with the polyether coating retained 91% of their room-temperature capacity at minus 20 degrees Celsius, compared to 58% for uncoated batteries tested under identical conditions.\""},{"key":"B","text":"\"The polyether compound used in the coating has a molecular weight of approximately 4,700 daltons, placing it in the medium-range for industrial polymer coatings.\""},{"key":"C","text":"\"Lithium-ion batteries without any coating typically perform best at temperatures between 20 and 25 degrees Celsius.\""},{"key":"D","text":"\"The Finnish startup has filed 14 patent applications related to polymer chemistry in the past three years.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The claim is that the polymer coating improves battery performance in cold conditions. The quotation showing coated batteries retaining 91% capacity at minus 20 degrees versus 58% for uncoated batteries provides direct comparative evidence of improved cold-weather performance. The quotation about molecular weight describes a physical property of the polymer but says nothing about its effect on battery performance. The quotation about optimal temperature range for uncoated batteries provides background on standard behavior without addressing the coating''s impact. The quotation about patent applications describes the company''s intellectual property activity, which is unrelated to whether the coating actually improves performance.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AT1IMC', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from the study, if accurate, would most directly undermine Vargas and Shin''s conclusion?', E'A 2024 analysis by economists Rosa Vargas and Jun-Ho Shin examined wage data from 1,247 independent bookstores across 19 countries and concluded that bookstores located within 500 meters of a university campus paid their employees an average of 17% more than comparable bookstores in non-university neighborhoods. Vargas and Shin argued that this wage premium was driven by competition: university-adjacent bookstores must compete for workers with campus employers — libraries, administrative offices, and campus retail — that typically offer structured benefits and predictable schedules, forcing nearby bookstores to raise wages to attract and retain staff.', $lyceon_json$[{"key":"A","text":"Bookstores located near large hospital complexes — which also offer structured benefits and predictable schedules — pay wages statistically indistinguishable from bookstores in neighborhoods with no major institutional employers."},{"key":"B","text":"University-adjacent bookstores in the sample reported higher annual revenue per employee than non-university bookstores, which could fund higher wages."},{"key":"C","text":"Campus employers in the sampled university neighborhoods posted 23% more job openings per quarter than employers in comparable non-university neighborhoods."},{"key":"D","text":"Bookstore employees in university neighborhoods were more likely to hold postgraduate degrees than employees at non-university bookstores."}]$lyceon_json$::jsonb, 'A', NULL, E'Vargas and Shin''s conclusion is that university-adjacent bookstores pay more because they compete with nearby campus employers offering structured benefits and predictable schedules. If bookstores near hospitals — institutions that similarly offer structured benefits and predictable schedules — do not pay a comparable wage premium, then proximity to institutions with those employment characteristics does not generally drive bookstore wages up. This would undermine the proposed competition mechanism. The finding about higher revenue per employee provides an alternative explanation for higher wages but does not challenge the competition mechanism itself. The finding about more campus job postings would actually support the conclusion by confirming stronger labor market competition near universities. The finding about employees holding postgraduate degrees suggests a workforce composition difference but does not directly address whether institutional labor competition drives the wage premium.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AYPFR1', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Neuroscientist Priya Venkataraman conducted experiments in which 178 participants were asked to memorize lists of 23 unrelated words under two conditions: in the first, participants studied the words in a silent room; in the second, they studied while listening to recordings of conversational speech in a language they did not understand. Counterintuitively, participants in the foreign-language background condition recalled an average of 14.7 words correctly, compared to 12.1 words in the silent condition. Venkataraman noted that incomprehensible speech, unlike silence, provides continuous auditory stimulation without competing for the brain''s language-processing resources, and she proposed that this stimulation maintains a moderate level of cortical arousal that ________', $lyceon_json$[{"key":"A","text":"keeps attention circuits sufficiently engaged to support encoding without creating the semantic interference that comprehensible speech would produce."},{"key":"B","text":"suppresses the brain's tendency to form long-term memories, redirecting cognitive effort toward short-term rehearsal strategies."},{"key":"C","text":"activates the same neural pathways used for music processing, which have been shown to inhibit word memorization."},{"key":"D","text":"reduces cortical arousal below the threshold needed for efficient memory encoding, forcing participants to compensate with increased effort."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that incomprehensible speech provides auditory stimulation without competing for language-processing resources, and that this maintains moderate cortical arousal. Since participants in this condition recalled more words, the logical completion is that the arousal keeps attention engaged enough to support encoding without the semantic interference that understandable speech would introduce. The option about suppressing long-term memory formation contradicts the observed result — participants recalled more words, not fewer. The option about activating music-processing pathways introduces neural mechanisms not mentioned in the passage and claims an inhibitory effect that contradicts the improved recall. The option about reducing cortical arousal directly contradicts the passage, which states the stimulation maintains arousal rather than reducing it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BDGOGC', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief informational report about an unusual geological discovery and wants to convey what was found and why it surprised researchers. Which choice most effectively uses information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CHATY0', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Paleobotanist Reiko Matsuda-Fernandez has challenged the conventional interpretation of fossilized leaf wax compounds found in late Miocene sediments from the Siwalik Hills of northern Pakistan. Earlier researchers had interpreted high concentrations of long-chain n-alkanes with odd carbon numbers (C29 and C31) as evidence that dense C3 forests dominated the region until approximately 7.5 million years ago, when a shift to C4 grasslands occurred. Matsuda-Fernandez argues, however, that these n-alkane signatures could equally derive from xerophytic C3 shrubs adapted to arid conditions — plants that produce leaf waxes chemically indistinguishable from those of forest trees but that thrive in open, dry landscapes. If her interpretation is correct, the Siwalik sediments may record not a forested environment giving way to grassland, but rather an already-open shrubland transitioning between two types of arid-adapted vegetation, fundamentally altering the timeline of forest retreat in South Asia.', $lyceon_json$[{"key":"A","text":"Matsuda-Fernandez proposes that leaf wax evidence from the Siwalik Hills may reflect arid shrubland rather than dense forest, which would change the understood timing of forest decline in the region."},{"key":"B","text":"The Siwalik Hills contained both C3 forests and C4 grasslands simultaneously during the late Miocene, contradicting prior assumptions of a sequential transition."},{"key":"C","text":"Long-chain n-alkanes with odd carbon numbers are unreliable as paleobotanical evidence because they degrade unpredictably in sedimentary environments."},{"key":"D","text":"Matsuda-Fernandez has determined that xerophytic C3 shrubs were the dominant vegetation type in northern Pakistan throughout the entire Miocene epoch."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on Matsuda-Fernandez''s argument that chemical signatures previously attributed to forests could instead come from arid shrubs, potentially revising the timeline of forest retreat in South Asia. The option about leaf wax evidence reflecting shrubland and altering the understood timeline captures this main idea. The option about simultaneous forests and grasslands introduces a coexistence scenario the passage does not describe — the debate is about what the C3 signature represents, not about simultaneous vegetation types. The option about n-alkane degradation fabricates a reliability concern not raised in the passage; the issue is interpretive ambiguity, not chemical degradation. The option claiming Matsuda-Fernandez determined shrub dominance throughout the entire Miocene overstates her argument — she proposes a reinterpretation of late Miocene evidence, not a claim about the full epoch.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DOMHMO', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a letter to a museum director and wants to propose an exhibit theme by arguing that a single historical figure''s work had lasting influence across two distinct fields. Which choice most effectively uses information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FQRG5V', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Historian Lucinda Ferreira has argued that the Portuguese enclave trading system in the Indian Ocean during the sixteenth century depended less on military superiority than on the ability of local intermediaries -- known as casados -- to negotiate commercial agreements with indigenous merchant networks. Several scholars have supported this view by pointing to records from Goa and Malacca showing that casados brokered over 60% of the spice contracts between 1520 and 1570. _______ maritime archaeologist Kenji Taniguchi has cautioned that these commercial records may overstate the casados'' autonomous role, since Portuguese crown officials routinely reviewed and ratified the contracts, suggesting that the intermediaries operated within, rather than independently of, a centralized imperial framework.', $lyceon_json$[{"key":"A","text":"By extension,"},{"key":"B","text":"Even so,"},{"key":"C","text":"In confirmation,"},{"key":"D","text":"To that end,"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentences before the blank present Ferreira''s argument about casados'' importance and supporting evidence from commercial records. The sentence after the blank introduces Taniguchi''s cautionary counterpoint -- that crown officials ratified the contracts, meaning the casados may not have been as autonomous as the records suggest. "Even so," correctly signals that despite the supporting evidence just presented, a complicating reservation follows. "By extension," implies that Taniguchi''s point is a logical expansion of the supporting evidence, but his observation challenges rather than extends it. "In confirmation," suggests Taniguchi is corroborating the previous evidence, but he is introducing a reservation that complicates the interpretation of that evidence. "To that end," implies Taniguchi''s observation serves the same goal as the preceding argument, but his caution works against the claim that casados operated autonomously.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FTKHAD', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what is the primary factor that Lindqvist identifies as responsible for the shift she describes?', E'Architectural historian Maren Lindqvist examined 89 municipal swimming pool designs submitted to Swedish city councils between 1948 and 1971. She found that pools designed before 1958 overwhelmingly featured open-air layouts with large spectator galleries, while those designed after 1962 were almost exclusively enclosed, indoor facilities with minimal seating for observers. Lindqvist attributes this transition primarily to a 1959 Swedish Public Health Board directive that reclassified public swimming from a competitive spectacle to a therapeutic and hygienic activity. The directive encouraged municipalities to prioritize year-round accessibility and water temperature regulation over accommodation for audiences, leading architects to adopt enclosed designs that could maintain controlled environments regardless of season.', $lyceon_json$[{"key":"A","text":"Rising construction costs after 1958 made it impractical for Swedish municipalities to build open-air pools with large spectator areas."},{"key":"B","text":"A 1959 Public Health Board directive reclassifying swimming as a therapeutic activity prompted architects to design enclosed, climate-controlled pools rather than open-air spectator venues."},{"key":"C","text":"Swedish architects independently concluded that indoor pools were aesthetically superior to open-air designs during the early 1960s."},{"key":"D","text":"Declining public attendance at competitive swimming events forced municipalities to reduce spectator seating in new pool designs."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage explicitly states that Lindqvist attributes the design shift primarily to the 1959 Public Health Board directive, which reclassified swimming from a competitive spectacle to a therapeutic and hygienic activity, prompting enclosed, climate-controlled designs. The option about rising construction costs introduces an economic factor not mentioned in the passage. The option about architects independently favoring indoor aesthetics fabricates a motivation the text does not discuss. The option about declining attendance at competitive events introduces a demand-side explanation that the passage never addresses.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HZI59B', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Glaciologist Renata Voronova has spent nine years mapping the retreat of the Storbreen glacier in southern Norway. Her measurements indicate that the glacier''s terminus receded by an average of 23 meters per year between 2015 and 2024. _______ Voronova has observed that meltwater from the retreating glacier has created a new lake at its base, which local ecologists are now studying as a freshwater habitat.', $lyceon_json$[{"key":"A","text":"In contrast,"},{"key":"B","text":"Additionally,"},{"key":"C","text":"Therefore,"},{"key":"D","text":"Regardless,"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence before the blank describes one of Voronova''s findings -- the rate of glacial retreat -- and the sentence after the blank introduces a separate, related observation she has made about meltwater forming a new lake. "Additionally," correctly signals that supplementary information is being introduced alongside the first finding. "In contrast," implies an opposition between the two observations, but the lake formation is a consequence of the same retreat, not a contrasting phenomenon. "Therefore," implies the lake observation is a logical conclusion drawn from the retreat rate, but it is presented as a separate empirical observation rather than a deduction. "Regardless," suggests the lake finding persists despite some obstacle, but no obstacle has been introduced.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IBUQ85', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly support Okonkwo''s hypothesis?', E'Marine biologist Adaeze Okonkwo studied populations of the West African fiddler crab (Uca tangeri) along 23 estuaries in Ghana and Côte d''Ivoire. She observed that male crabs in estuaries with high concentrations of suspended clay particles had significantly larger major claws — averaging 41% of total body mass — than males in clear-water estuaries, where major claws averaged 29% of body mass. Okonkwo hypothesized that in turbid water, where visual signals are attenuated, males have evolved disproportionately large claws because the exaggerated size compensates for reduced visibility, ensuring that claw-waving courtship displays remain detectable to females at distances where smaller claws would be obscured.', $lyceon_json$[{"key":"A","text":"In laboratory experiments using artificially turbid water, female Uca tangeri approached males with experimentally enlarged claws at rates 67% higher than males with standard-sized claws, but showed no such preference in clear water."},{"key":"B","text":"Suspended clay concentrations in Ghanaian estuaries fluctuate seasonally, peaking during the rainy season from May through September."},{"key":"C","text":"Male fiddler crabs in clear-water estuaries spend more total time per day engaged in claw-waving displays than males in turbid estuaries."},{"key":"D","text":"The diet of Uca tangeri in turbid estuaries includes a higher proportion of calcium-rich benthic organisms, which could promote claw growth."}]$lyceon_json$::jsonb, 'A', NULL, E'Okonkwo''s hypothesis is that larger claws evolved in turbid water because they compensate for reduced visibility during courtship displays. The finding that females in turbid water preferentially approach males with enlarged claws — but show no such preference in clear water — directly supports the idea that claw size matters more when visibility is low, confirming the hypothesized link between turbidity, claw size, and female detection. The finding about seasonal clay fluctuations provides environmental context but does not address whether larger claws aid courtship in turbid conditions. The finding about display duration in clear-water estuaries describes a behavioral difference without connecting claw size to female detection in turbid water. The finding about calcium-rich diets proposes an alternative, non-evolutionary mechanism for claw growth that would undermine rather than support the hypothesis that larger claws are an adaptive response to turbidity.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J85JAA', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the passages, how would Park most likely respond to Alvarez''s claim about bilingual education?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LRF4T0', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Architect Roshan Mehta designed a community library in Jaipur whose facade incorporates geometric patterns drawn from Mughal tilework _____ the interplay of sandstone and blue ceramic creates what Mehta describes as a dialogue between structural pragmatism and ornamental heritage.', $lyceon_json$[{"key":"A","text":"tilework, the"},{"key":"B","text":"tilework; the"},{"key":"C","text":"tilework the"},{"key":"D","text":"tilework, and; the"}]$lyceon_json$::jsonb, 'B', NULL, E'The blank separates two independent clauses: one about the facade''s incorporation of geometric patterns and another about the interplay of materials. A semicolon correctly joins two closely related independent clauses without a coordinating conjunction. A comma alone ("tilework, the") produces a comma splice because no conjunction follows. Removing all punctuation ("tilework the") fuses two independent clauses into a run-on sentence. Combining a comma, a conjunction, and a semicolon ("tilework, and; the") is redundant and malformed: the conjunction already joins the clauses, making the semicolon incorrect, and the semicolon improperly interrupts the second clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NO34HD', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'In 2023, a team of entomologists from the University of São Paulo reported that colonies of the leafcutter ant Atta laevigata cultivate not one but three distinct species of fungus in their underground gardens. Previous studies had assumed that each colony maintained a single fungal cultivar, but by sequencing DNA from fungal samples taken at 37 different chamber depths in eleven colonies across the Cerrado biome, the researchers found that all colonies hosted a primary cultivar alongside two supplementary species. The supplementary fungi, though present in smaller quantities, produced enzymes capable of breaking down lignin — a tough plant polymer that the primary cultivar cannot digest — suggesting that the ants'' agricultural system is more biochemically versatile than a single-crop model would allow.', $lyceon_json$[{"key":"A","text":"Leafcutter ant colonies cultivate multiple fungal species rather than a single one, and the supplementary fungi contribute enzymes that expand the colony's ability to digest plant material."},{"key":"B","text":"Lignin is the primary nutrient source for leafcutter ant colonies in the Cerrado biome."},{"key":"C","text":"The University of São Paulo team was the first to use DNA sequencing to study fungal species in ant gardens."},{"key":"D","text":"Leafcutter ants prefer to cultivate supplementary fungi over their primary cultivar because supplementary fungi grow faster in deeper chambers."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes the discovery that leafcutter ant colonies maintain three fungal species rather than one, with the supplementary fungi providing lignin-digesting enzymes that the primary cultivar lacks. The option about multiple fungal species expanding digestive capability captures this central point. The option identifying lignin as the primary nutrient source misreads the passage — lignin is described as a tough polymer that supplementary fungi can break down, not as the ants'' main food source. The option about being the first to use DNA sequencing introduces a claim not made in the passage. The option about ants preferring supplementary fungi because of faster growth fabricates information absent from the text.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
