INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ORW7ZO', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Kenji Furukawa identified a previously undocumented species of bioluminescent jellyfish in the Sargasso Sea _____ the organism emits a pale green glow that intensifies when disturbed by passing currents.', $lyceon_json$[{"key":"A","text":"Sea, the"},{"key":"B","text":"Sea. The"},{"key":"C","text":"Sea the"},{"key":"D","text":"Sea and, the"}]$lyceon_json$::jsonb, 'B', NULL, E'Two independent clauses appear on either side of the blank: one describing Furukawa''s discovery and another describing the organism''s bioluminescent behavior. A period correctly separates these into two complete sentences. Using only a comma ("Sea, the") creates a comma splice, joining two independent clauses without a coordinating conjunction. Omitting all punctuation ("Sea the") produces a fused sentence. Adding "and" with an unnecessary comma before "the" ("Sea and, the") improperly interrupts the second clause with punctuation that has no grammatical function.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PM2431', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the textile cooperative had already secured funding from two regional development banks, its directors _____ to postpone the expansion of dyeing facilities until an independent environmental review could confirm that the wastewater treatment system met federal discharge standards.', $lyceon_json$[{"key":"A","text":"decides"},{"key":"B","text":"have decided"},{"key":"C","text":"decided"},{"key":"D","text":"deciding"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence establishes a past-tense frame with "had already secured" and "could confirm," so the main clause verb must also be in the past tense. The plural subject "directors" requires a plural verb form. The simple past "decided" is both plural-compatible and in the correct tense. The third-person singular present "decides" fails on both number agreement (singular for a plural subject) and tense (present instead of past). The present perfect "have decided" agrees in number but shifts to the present perfect tense, breaking consistency with the past-tense narrative frame. The present participle "deciding" is not a finite verb form and cannot serve as the main predicate of the clause, producing a sentence fragment.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2S8KVI7', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Textile conservator Elif Arslan examined 43 Ottoman silk brocade fragments held in European museum collections and catalogued between the sixteenth and seventeenth centuries. She found that 38 of the fragments had been cut along repeating pattern boundaries with surgical precision, preserving complete motif units, while the remaining five had been cut haphazardly, severing motifs mid-repeat. Arslan noted that all five haphazardly cut fragments came from collections assembled before 1620, whereas all 38 precisely cut fragments entered European collections after 1650. She concluded that ________', $lyceon_json$[{"key":"A","text":"before 1620, European collectors valued Ottoman silk primarily as raw textile material, whereas after 1650, collectors increasingly recognized the aesthetic importance of complete pattern repeats and cut fabrics accordingly."},{"key":"B","text":"Ottoman silk brocade production declined sharply in quality after 1650, making it easier for European collectors to identify pattern boundaries."},{"key":"C","text":"the five haphazardly cut fragments were originally part of the same larger textile, which was divided among several collections before 1620."},{"key":"D","text":"Ottoman weavers changed their pattern-repeat dimensions after 1650, making the boundaries between motif units more visible to untrained observers."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage contrasts haphazard cutting in pre-1620 collections with precise motif-preserving cutting in post-1650 collections. The logical conclusion is that European attitudes toward Ottoman silk changed over time — earlier collectors treated it as material to be used without regard for pattern integrity, while later collectors recognized and preserved complete pattern units. The option about declining production quality after 1650 introduces a manufacturing claim unsupported by the passage and illogically connects lower quality to easier pattern identification. The option about the five fragments originating from one textile is speculative and does not account for the broader chronological pattern. The option about Ottoman weavers changing repeat dimensions shifts the explanation to production methods rather than collecting practices, which is not supported by the text.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SVIZEA', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The review board recommended that the pharmaceutical company _____ all clinical trial data within ninety days of completing its Phase III study so that independent researchers could replicate the findings before regulatory approval was granted.', $lyceon_json$[{"key":"A","text":"discloses"},{"key":"B","text":"disclosed"},{"key":"C","text":"disclose"},{"key":"D","text":"will disclose"}]$lyceon_json$::jsonb, 'C', NULL, E'The verb "recommended" followed by "that" introduces a mandative subjunctive clause, which in Standard English requires the base (uninflected) form of the verb regardless of the subject''s person or number. The bare infinitive "disclose" is the correct subjunctive form. The third-person singular present indicative "discloses" would be appropriate in a declarative statement but is incorrect in a subjunctive clause following a verb of recommendation. The past-tense "disclosed" incorrectly shifts the clause into the indicative past, misrepresenting the board''s recommendation as a completed action rather than a directive. The modal future "will disclose" introduces a tense marker that is not standard in mandative subjunctive clauses, which require the uninflected base form without auxiliary verbs.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TM1J70', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the passage?', E'The Voyager 1 spacecraft, launched in 1977, carries a gold-plated phonograph record containing sounds and images selected to portray the diversity of life and culture on Earth. The record includes greetings in fifty-five languages, musical selections ranging from Beethoven to Blind Willie Johnson, and 116 images depicting human beings, animals, and natural landscapes.', $lyceon_json$[{"key":"A","text":"To describe the contents and purpose of an object aboard a spacecraft"},{"key":"B","text":"To argue that the Voyager mission was the most important space program of the twentieth century"},{"key":"C","text":"To compare the scientific instruments carried by Voyager 1 with those of later probes"},{"key":"D","text":"To explain the technical process by which the gold record was manufactured"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage introduces the Voyager golden record and catalogs what it contains — greetings, music, and images chosen to represent Earth. Its function is to describe the object and its representative purpose. Arguing that Voyager was the most important space program overstates the passage, which makes no evaluative claim about the mission''s relative significance. Comparing scientific instruments across different probes has no basis in the text, which discusses the cultural record rather than scientific equipment. Explaining the manufacturing process misidentifies the focus; the passage describes what the record contains, not how it was physically produced.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UGOLR3', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the passage, "tempered" most nearly means', E'Although the director''s initial enthusiasm for the excavation was tempered by the discovery that nearly forty percent of the site had been disturbed by twentieth-century construction, she nevertheless secured funding to continue digging in the undisturbed southeastern quadrant, where ground-penetrating radar had revealed promising anomalies.', $lyceon_json$[{"key":"A","text":"heated"},{"key":"B","text":"moderated"},{"key":"C","text":"enraged"},{"key":"D","text":"manufactured"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes the director''s enthusiasm being partially restrained by disappointing news about site disturbance, though not entirely extinguished since she still pursued funding. "Moderated" correctly conveys the sense of an emotion being lessened or restrained in intensity. "Heated" means to raise the temperature of something, which is incoherent when applied to the effect of bad news on enthusiasm. "Enraged" means to fill with violent anger, which contradicts the passage''s depiction of enthusiasm being dampened rather than transformed into fury. "Manufactured" means to produce goods in a factory or to fabricate something, which has no logical connection to the diminishing of enthusiasm.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UHP8GT', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The panel of geologists studying seismic activity beneath the Apennine Mountains _____ a revised hazard assessment every March to ensure that local infrastructure guidelines remain current.', $lyceon_json$[{"key":"A","text":"publish"},{"key":"B","text":"publishes"},{"key":"C","text":"are publishing"},{"key":"D","text":"have published"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject is "panel," a singular collective noun, so the verb must agree in the singular. The phrase "every March" signals a habitual, recurring action best expressed in the simple present tense. The third-person singular present "publishes" satisfies both requirements. The bare plural form "publish" fails to agree with the singular subject "panel." The present progressive "are publishing" is plural, failing number agreement, and implies an action in progress rather than a habitual occurrence. The present perfect "have published" is also plural, failing number agreement, and suggests a completed action rather than an ongoing annual practice.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WR1DUI', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Paleontologist Celeste Navarro has spent over a decade excavating fossilized pollen grains from late Cretaceous sediment layers in _____ her stratigraphic analyses have reshaped scholarly understanding of how flowering plants spread across the ancient supercontinent.', $lyceon_json$[{"key":"A","text":"Patagonia, Argentina;"},{"key":"B","text":"Patagonia Argentina;"},{"key":"C","text":"Patagonia, Argentina,"},{"key":"D","text":"Patagonia Argentina,"}]$lyceon_json$::jsonb, 'A', NULL, E'Two conventions operate here simultaneously. First, the city-region and country pair "Patagonia, Argentina" requires a comma between the geographic components. Second, two independent clauses flank the blank, so a semicolon is needed to join them correctly. The combination "Patagonia, Argentina;" satisfies both requirements. Omitting the comma between the geographic names ("Patagonia Argentina;") violates the convention for punctuating geographic pairs, even though the semicolon correctly handles the clause boundary. Using a comma after "Argentina" instead of a semicolon ("Patagonia, Argentina,") properly punctuates the geographic pair but creates a comma splice between the two independent clauses. Omitting both the internal comma and using only a trailing comma ("Patagonia Argentina,") fails on both counts: no separator between the geographic names and a comma splice between independent clauses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y90SCV', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the third sentence in the passage ("Yet Okafor found . . . surface temperature")?', E'Climate scientist Adaeze Okafor set out to test the widespread assumption that urban green roofs consistently lower building energy costs in tropical climates. Her team monitored energy consumption in 41 commercial buildings across three West African cities over twenty-seven months, comparing structures with green roofs to matched controls with conventional roofing. Yet Okafor found that during the humid season — when ambient humidity exceeded eighty-five percent for weeks at a time — green roofs actually increased cooling costs by an average of nine percent, because the saturated soil layer trapped heat rather than facilitating evaporative cooling, effectively raising the roof''s surface temperature. Okafor concludes that the energy benefits of green roofs depend critically on seasonal humidity patterns, a variable most existing cost models fail to incorporate.', $lyceon_json$[{"key":"A","text":"It presents the unexpected finding that complicates the assumption the passage opened with"},{"key":"B","text":"It provides additional evidence supporting the claim that green roofs reduce energy costs"},{"key":"C","text":"It describes the methodology Okafor used to collect temperature data from the buildings"},{"key":"D","text":"It introduces a competing researcher's objection to Okafor's experimental design"}]$lyceon_json$::jsonb, 'A', NULL, E'The first sentence establishes the assumption being tested — that green roofs lower energy costs in tropical climates. The third sentence, introduced by the contrastive "Yet," reveals that during humid seasons green roofs actually increased cooling costs, directly complicating the original assumption. Providing evidence that green roofs reduce costs contradicts the sentence''s content, which shows the opposite effect during humid conditions. Describing data collection methodology misidentifies the sentence''s role; it reports a result, not a procedure — the methodology is outlined in the preceding sentence. Introducing a competing researcher''s objection is unsupported; the sentence presents Okafor''s own finding, not criticism from another scientist.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZMPHGK', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a research summary and wants to present a finding that initially appears to support a hypothesis but, upon closer examination, actually undermines it. Which choice most effectively uses information from the notes to accomplish this goal?', E'Notes:
